/* Maintenance: dashboard + workspaces (vehicles, work orders, schedule, inspections, parts, documents, reports) */
const M = () => S.maint;
const pnl = (title, body, opts = {}) => `<section class="pnl" style="${opts.st || ''}"><div class="pnl-h">${opts.back ? `<button class="phb" ${opts.back.startsWith('#') ? `data-go="${opts.back}"` : `data-act="${opts.back}"`}>${ic('arrowl', 18)}</button>` : opts.icon ? `<span class="phb">${ic(opts.icon, 18)}</span>` : ''}<span class="t">${title}</span>${opts.right || ''}</div><div class="pnl-b" ${opts.keep ? `data-keep="${opts.keep}"` : ''} style="${opts.bst || ''}">${body}</div></section>`;
const mtabs = (key, tabs, cur) => `<div class="tabs">${tabs.map(t => { const [v, l] = Array.isArray(t) ? t : [t, t]; return `<button class="tab ${cur === v ? 'on' : ''}" data-act="set" data-k="u:${key}" data-v="${esc(v)}">${l}</button>`; }).join('')}</div>`;
const partQty = p => M().partQty[p.code] ?? p.qty;
const partStatus = p => { const q = partQty(p); return q === 0 ? 'Out of Stock' : q < p.reorder ? 'Low Stock' : 'In Stock'; };
const allParts = () => [...DATA.parts, ...(M().extraParts || [])];
const mmVeh = () => DATA.mmVehicles.find(v => v.no === (UI.mv || 'GJ01EF9012')) || DATA.mmVehicles[0];
const MBASE = () => CUR.role === 'admin' ? '#/admin/maintenance?s=' : '#/maint/';
const mlink = k => CUR.role === 'admin' ? `#/admin/maintenance?s=${{ vehicles: 'service-requests', workorders: 'repair-work-orders', schedule: 'preventive-maintenance', inspections: 'inspections', parts: 'spare-parts-inventory', documents: 'documents', reports: 'maintenance-reports', dashboard: 'overview' }[k]}` : `#/maint/${k}`;

/* ---------------- Dashboard ---------------- */
function maintDashboard() {
  const sel = UI.msel || 'GJ01CD5678', tab = UI.mtab || 'Service Schedule', f = ui('mdf', { q: '', st: 'All Status', ty: 'All Service Types', v: 'All Vehicles', p: 1 });
  const sched = [...M().schedule, ...DATA.serviceSchedule].map(r => ({ ...r, status: M().serviceDone.includes(r.v + r.type) ? 'Completed' : r.status }));
  const list = sched.filter(r => (!f.q || (r.v + r.model + r.type).toLowerCase().includes(f.q.toLowerCase())) && (f.st === 'All Status' || r.status === f.st) && (f.ty === 'All Service Types' || r.type === f.ty) && (f.v === 'All Vehicles' || r.v === f.v));
  const pg = paginate(list, f.p, 6);
  const cur = sched.find(r => r.v === sel) || sched[1];
  const veh = allVehicles().find(v => v.no === cur.v) || DATA.vehicles[1];
  const wo = M().workOrders;
  let tbl = '';
  if (tab === 'Service Schedule') tbl = `<div class="filters" style="border:0;padding:10px 12px 6px;margin:0">${searchBox('u:mdf.q', 'Search by vehicle number, model, service type...', f.q, 'u:mdf.p')}${sel_('u:mdf.st', ['All Status', 'Scheduled', 'Overdue', 'Due Soon', 'Due Today', 'Completed'], f.st)}${sel_('u:mdf.ty', ['All Service Types', ...new Set(sched.map(s => s.type))], f.ty)}${sel_('u:mdf.v', ['All Vehicles', ...new Set(sched.map(s => s.v))], f.v)}</div>
    <table class="tbl"><thead><tr><th style="width:28px">${chk(false)}</th><th>Vehicle No.</th><th>Vehicle Details</th><th>Service Type</th><th>Last Service</th><th>Next Due Date</th><th>Due In</th><th>Status</th><th>Actions</th></tr></thead><tbody>${pg.rows.map(r => `<tr class="clk ${r.v === sel ? 'rsel' : ''}" data-act="set" data-k="u:msel" data-v="${r.v}"><td>${chk(r.v === sel)}</td><td><span style="display:block;width:72px">${busSide(72, 'white')}</span></td><td><div class="t1">${r.v}</div><div class="t2">${r.model}</div><div class="t2">${r.seats}</div></td><td>${r.type}</td><td>${r.last}</td><td>${r.next}</td><td class="${r.due === 'Overdue' ? 'c-red' : r.due === 'Today' ? 'c-orange' : ''}" style="${r.due === 'Overdue' || r.due === 'Today' ? 'text-decoration:underline' : ''}">${r.status === 'Completed' ? '-' : r.due}</td><td>${badge(r.status)}</td><td><div class="acts"><button class="ibtn" data-act="mreschedule" data-v="${r.v}" data-t="${r.type}" title="Reschedule">${ic('cal', 15)}</button><button class="ibtn" data-act="mcreatewo" data-v="${r.v}" data-t="${r.type}" title="Create work order">${ic('edit', 15)}</button><button class="ibtn" data-act="dd" data-dd="mrow" data-v="${r.v}" data-t="${r.type}" data-w="200">${ic('more', 15)}</button></div></td></tr>`).join('') || emptyRow(9)}</tbody></table>${pager('u:mdf.p', pg, list.length + (list.length === sched.length ? 46 : 0), 'vehicles', 'u:mdf.per', 10)}`;
  else if (tab === 'Work Orders') tbl = woTable(wo);
  else if (tab === 'Vehicle Inspections') tbl = `<table class="tbl"><thead><tr><th>Date</th><th>Vehicle</th><th>Type</th><th>Inspector</th><th>Result</th><th>Next Due</th><th></th></tr></thead><tbody>${[['26 Sep 2026', 'GJ01EF9012', 'Routine Inspection', 'Ramesh Patel', 'Pass', '26 Dec 2026'], ['22 Sep 2026', 'GJ01AB1234', 'Pre-Trip', 'S. Kumar', 'Pass', '29 Sep 2026'], ['21 Sep 2026', 'GJ01CD5678', 'Monthly', 'A. Mehta', 'Pass', '21 Oct 2026'], ['20 Sep 2026', 'GJ01EF9012', 'Pre-Trip', 'R. Patel', 'Fail', '24 Sep 2026'], ['19 Sep 2026', 'GJ01GH3456', 'Quarterly', 'P. Yadav', 'Pass', '19 Dec 2026']].map(r => `<tr class="clk" data-go="${mlink('inspections')}"><td>${r[0]}</td><td class="t1">${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${badge(r[4])}</td><td>${r[5]}</td><td>${ic('right', 16)}</td></tr>`).join('')}</tbody></table>`;
  else if (tab === 'Breakdown Requests') tbl = `<table class="tbl"><thead><tr><th>Request</th><th>Vehicle</th><th>Reported By</th><th>Location</th><th>Issue</th><th>Status</th><th></th></tr></thead><tbody>${[['BR-2026-031', 'GJ01GH3456', 'Manoj Das', 'Sargasan Circle', 'Engine overheating', 'In Progress'], ['BR-2026-030', 'GJ01EF9012', 'Imran Shaikh', 'R-03 East Zone', 'Engine overheated, stopped', 'In Progress'], ['BR-2026-029', 'GJ01OP5566', 'Nitin Chauhan', 'Depot', 'Battery failure', 'Resolved']].map(r => `<tr><td class="t1">${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${badge(r[5])}</td><td>${r[5] !== 'Resolved' ? `<button class="btn btn-soft btn-sm" data-act="mcreatewo" data-v="${r[1]}" data-t="Breakdown" data-ty="Breakdown">Create WO</button>` : ''}</td></tr>`).join('')}</tbody></table>`;
  else if (tab === 'Spare Parts') tbl = partsTable(allParts().slice(0, 8), true);
  else tbl = `<table class="tbl"><thead><tr><th>Vendor / Garage</th><th>Type</th><th>Phone</th><th>Email</th><th>Open Orders</th><th></th></tr></thead><tbody>${[...DATA.suppliers, ...M().extraSuppliers].map((s, i) => `<tr><td class="t1">${s.name}</td><td>${s.type}</td><td>${s.phone}</td><td>${s.email}</td><td>${(i * 2 + 1) % 5}</td><td><button class="btn btn-outline btn-sm" data-act="call" data-who="${s.name}">${ic('phone', 14)}Call</button></td></tr>`).join('')}</tbody></table>`;
  const overdueDays = { 'GJ01CD5678': 16, 'GJ01GH3456': 8 }[cur.v];
  return `<div class="ph"><div><h1>Maintenance Dashboard</h1><p>Manage vehicle maintenance, service schedules, inspections and repair work orders.</p></div><div class="ph-act"><button class="datebtn" data-act="dd" data-dd="date" data-w="220">${ic('cal', 17)}${UI.date || TODAY}${ic('down', 15)}<span style="border-left:1px solid var(--line);height:22px;margin:0 2px"></span>${ic('down', 15)}</button></div></div>
  <div class="kpis" style="grid-template-columns:repeat(6,1fr)">
    ${kpi({ c: 'blue', i: 'tools', v: '52', l: 'Total Vehicles', f: `48 Active ${fsep} 3 In Maintenance ${fsep} 1 Inactive`, go: mlink('vehicles') })}
    ${kpi({ c: 'green', i: 'gear', v: '6', l: 'In Maintenance', f: `5 Scheduled ${fsep} 1 Breakdown`, go: mlink('workorders') })}
    ${kpi({ c: 'orange', i: 'ops', v: '12', l: 'Due for Service', f: `<span class="c-red m5">3 Overdue</span>`, act: 'set', data: 'data-k="u:mdf.st" data-v="Overdue"' })}
    ${kpi({ c: 'red', i: 'warn', v: '4', l: 'Critical Issues', f: `<span class="link" style="color:#dc2626">View Details ${ic('arrowr', 14)}</span>`, act: 'mcritical' })}
    ${kpi({ c: 'purple', i: 'file', v: String(wo.filter(w => w.status !== 'Closed').length + 15), l: 'Open Work Orders', f: `12 In Progress ${fsep} 6 Pending`, act: 'set', data: 'data-k="u:mtab" data-v="Work Orders"' })}
    ${kpi({ c: 'blue', i: 'box', v: '850', l: 'Spare Parts in Stock', f: `<span class="c-red m5">27 Low Stock</span>`, go: mlink('parts') })}</div>
  <div class="g rgrid" style="grid-template-columns:minmax(0,.95fr) minmax(0,1.25fr) minmax(0,1.1fr) minmax(0,.95fr);margin-bottom:14px">
    <div class="card">${cardH('Maintenance Status (Fleet)')}<div class="card-b row" style="gap:18px">${donut([{ v: 45, c: '#16a34a' }, { v: 3, c: '#f97316' }, { v: 2, c: '#facc15' }, { v: 1, c: '#ef4444' }, { v: 1, c: '#64748b' }], 116, 17, '<div class="v">52</div><div class="l">Vehicles</div>')}<div class="lg" style="flex:1">${[['#16a34a', 'On Road', 45], ['#f97316', 'In Maintenance', 3], ['#facc15', 'Under Inspection', 2], ['#ef4444', 'Breakdown', 1], ['#64748b', 'Inactive', 1]].map(x => legendRow(x[0], x[1], x[2]).replace('dotc', 'sqc')).join('')}</div></div></div>
    <div class="card">${cardH('Service Due (Next 30 Days)')}<div class="card-b row" style="gap:10px;align-items:flex-start"><div style="flex:1">${bars({ w: 260, h: 150, pl: 22, labels: ['Today', '27 Sep', '4 Oct', '11 Oct', '18 Oct', '25 Oct'], series: [{ v: [2, 1, 0, 0, 0, 0], c: '#ef4444' }, { v: [0, 5, 8, 3, 0, 0], c: '#f97316' }, { v: [0, 0, 2, 2, 7, 7], c: '#facc15' }], ticks: [0, 2, 4, 6, 8, 10], bw: .8 })}</div><div class="lg" style="width:128px;margin-top:8px;font-size:12px">${[['#ef4444', 'Overdue', 3], ['#f97316', 'Due (0-7 days)', 5], ['#facc15', 'Due (8-30 days)', 9]].map(x => legendRow(x[0], x[1], x[2]).replace('dotc', 'sqc')).join('')}</div></div></div>
    <div class="card">${cardH('Maintenance Cost (This Month)')}<div class="card-b"><div class="row"><span class="b fs22">₹ 2,48,500</span><span class="c-green fs12 b row" style="gap:2px">${ic('arrowd', 13)}12%</span><span class="fs12 mut">vs last month</span></div>${bars({ w: 330, h: 120, labels: ['Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep'], series: [{ v: [1.1, 1.6, 2.1, 1.6, 2.2, 3.4], c: ['#93b4f5', '#93b4f5', '#93b4f5', '#93b4f5', '#5b8ff0', '#1463ff'] }], ticks: [0, 1, 2, 3, 4], fmt: v => v ? v + 'L' : '0', hl: 5, bw: .5 })}</div></div>
    <div class="card">${cardH('Spare Parts Stock')}<div class="card-b row" style="gap:18px">${donut([{ v: 750, c: '#16a34a' }, { v: 27, c: '#facc15' }, { v: 8, c: '#ef4444' }, { v: 65, c: '#94a3b8' }], 116, 17, '<div class="v">850</div><div class="l">Total Parts</div>')}<div class="lg" style="flex:1">${[['#16a34a', 'In Stock', 750], ['#facc15', 'Low Stock', 27], ['#ef4444', 'Out of Stock', 8], ['#64748b', 'Not Tracked', '']].map(x => legendRow(x[0], x[1], x[2]).replace('dotc', 'sqc')).join('')}</div></div></div></div>
  <div class="row" style="margin-bottom:10px;gap:4px"><div class="tabs" style="flex:1;border:0">${[['Service Schedule', 'cal'], ['Work Orders', 'edit'], ['Vehicle Inspections', 'clip'], ['Breakdown Requests', 'warn'], ['Spare Parts', 'box'], ['Vendors & Garages', 'people']].map(t => `<button class="tab ${tab === t[0] ? 'on' : ''}" data-act="set" data-k="u:mtab" data-v="${t[0]}">${ic(t[1], 17)}${t[0]}</button>`).join('')}</div><button class="btn btn-outline" data-act="mexport">${ic('export', 16)}Export</button><button class="btn btn-primary" data-act="mschedule">${ic('plus', 16)}Schedule Service</button></div>
  <div class="split"><div class="card">${tbl}</div>
  <div class="card dp"><div class="dp-h"><span style="width:84px">${busSide(84, 'white')}</span><div style="flex:1"><div class="row"><b class="fs18">${cur.v}</b>${badge(cur.status)}</div><div class="fs12 mut mt4">${veh.model} &nbsp;| &nbsp;${veh.seats} Seater &nbsp;| &nbsp;${veh.fuelType}</div></div><button class="dp-close" data-act="set" data-k="u:msel" data-v="GJ01CD5678">${ic('x', 18)}</button></div>
    <div class="tabs mt12">${['Overview', 'Service History', 'Work Orders', 'Documents'].map(t => `<button class="tab ${(UI.mdt || 'Overview') === t ? 'on' : ''}" data-act="set" data-k="u:mdt" data-v="${t}">${t}</button>`).join('')}</div>
    ${(UI.mdt || 'Overview') === 'Overview' ? `<div class="g mt12" style="grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:10px"><div class="sbox"><div class="sec-t">Vehicle Information</div><dl class="kv">${[['busf', 'Vehicle No.', cur.v], ['bus', 'Model', veh.model], ['users', 'Capacity', veh.seats + ' Seater'], ['fuel', 'Fuel Type', veh.fuelType], ['odo', 'Current KM', num(veh.km) + ' KM'], ['wrench', 'Last Service', cur.last], ['cal', 'Next Due Date', `<span class="${cur.status === 'Overdue' ? 'c-red b' : ''}">${cur.next}${cur.status === 'Overdue' ? ' (Overdue)' : ''}</span>`]].map(x => `<dt>${ic(x[0], 14, 'style="color:#2563eb"')}${x[1]}</dt><dd>${x[2]}</dd>`).join('')}</dl></div>
      <div class="col" style="gap:10px">${cur.status === 'Overdue' ? `<div class="sbox" style="background:#fdeeee;border-color:#f8d4d4"><div class="b c-red fs14">Overdue Service</div><div class="fs12 mt4" style="color:#b91c1c">${cur.type} is overdue by ${overdueDays || 5} days.</div><button class="btn btn-danger btn-block mt12" data-act="mcreatewo" data-v="${cur.v}" data-t="${cur.type}">${ic('tools', 15)}Create Work Order</button></div>` : `<div class="sbox" style="background:#ecf9f0;border-color:#c9ecd6"><div class="b c-green fs14">${cur.status === 'Completed' ? 'Service Completed' : 'Next Service'}</div><div class="fs12 mt4">${cur.type} on ${cur.next}</div></div>`}
      <div class="sbox"><div class="sec-t">Quick Actions</div>${[['cal', 'Schedule Service', 'mschedule'], ['tools', 'Log Service', 'mlog'], ['clip', 'View Inspection Checklist', 'minspgo'], ['file', 'Download Service Report', 'dl']].map(x => `<button class="btn btn-soft btn-block btn-sm mt8" style="justify-content:flex-start" data-act="${x[2]}" data-v="${cur.v}" data-name="Service_Report_${cur.v}.pdf">${ic(x[0], 14)}${x[1]}</button>`).join('')}</div></div></div>
    <div class="sec-t mt12">Recent Maintenance Activity</div><table class="tbl compact"><tbody>${[['10 Jul 2026', 'Oil Change', '98,430 KM'], ['12 May 2026', 'Brake Inspection', '92,120 KM'], ['05 Mar 2026', 'General Checkup', '85,450 KM'], ['18 Jan 2026', 'AC Service', '80,230 KM']].map(r => `<tr><td>${ic('clock', 13, 'style="color:#94a3b8"')} ${r[0]}</td><td>${r[1]}</td><td class="tr mut">${r[2]}</td></tr>`).join('')}</tbody></table>`
    : (UI.mdt === 'Service History' ? historyList('All') : UI.mdt === 'Work Orders' ? `<div class="mt12">${M().workOrders.filter(w => w.v === cur.v).map(w => woCard(w)).join('') || '<div class="mut tc" style="padding:20px">No work orders for this vehicle</div>'}<button class="btn btn-primary btn-block mt12" data-act="mcreatewo" data-v="${cur.v}" data-t="${cur.type}">${ic('plus', 15)}Create Work Order</button></div>` : docList(cur.v))}
  </div></div>`;
}
const sel_ = (b, o, v) => sel(b, o, v, 'data-pg="u:mdf.p"');
function woCard(w) { return `<button class="mini" style="width:100%;text-align:left;margin-bottom:8px" data-act="mwoopen" data-id="${w.id}">${tile('wrench', '#2563eb', '#eaf1ff', 36, 18, 9)}<div style="flex:1"><div class="mv fs13">${w.id} | ${w.type}</div><div class="ml">${esc(w.desc)}</div></div>${badge(w.status)}</button>`; }
function woTable(list) { return `<table class="tbl"><thead><tr><th>Work Order</th><th>Type</th><th>Vehicle</th><th>Priority</th><th>Assigned To</th><th>Expected</th><th>Stage</th><th>Status</th></tr></thead><tbody>${list.map(w => `<tr class="clk" data-act="mwoopen" data-id="${w.id}"><td class="t1">${w.id}</td><td>${w.type}</td><td>${w.v}<div class="t2">${w.model}</div></td><td>${badge(w.priority, false, w.priority === 'Critical' ? 'red' : w.priority === 'High' ? 'orange' : 'gray')}</td><td>${esc(w.to)}</td><td>${w.exp}</td><td>${WOSTEPS[Math.min(w.step, 7)]}</td><td>${badge(w.status)}</td></tr>`).join('')}</tbody></table>`; }
function historyList(cat) {
  const all = [...M().extraHistory, ...DATA.maintHistory].filter(h => cat === 'All' || h.cat === cat);
  return `<div class="mt8">${all.map((h, i) => `<div class="tl2"><div class="d">${h.d}</div><div class="ln"><i></i>${i < all.length - 1 ? '<b></b>' : ''}</div><div class="row" style="flex:1;align-items:flex-start;padding:8px 0">${tile(h.ic, h.c, h.bg, 34, 18, 9)}<div style="flex:1"><div class="b fs13">${h.t}</div><div class="fs12 mut">${h.wo}</div><div class="fs12 mut">${esc(h.desc)}</div><div class="fs12 mt4">Cost: ${inr(h.cost)}</div></div>${badge('Completed', false)}</div></div>`).join('')}</div>`;
}
function docList(v) { return `<div class="mt12">${[...M().extraDocs, ...DATA.documents].filter(d => !v || d.v === v).slice(0, 6).map(d => `<button class="mini" style="width:100%;text-align:left;margin-bottom:8px" data-go="${mlink('documents')}">${tile(d.kind === 'img' ? 'image' : 'file', d.kind === 'img' ? '#2563eb' : '#ef4444', d.kind === 'img' ? '#eaf1ff' : '#fde8e8', 34, 17, 8)}<div style="flex:1;min-width:0"><div class="mv fs12 ellip">${d.name}</div><div class="ml">${d.type} | ${d.d}</div></div>${ic('download', 15, 'style="color:#2563eb"')}</button>`).join('') || '<div class="mut tc">No documents</div>'}</div>`; }
DDS.mrow = d => `<button class="dd-i" data-act="mmarkdone" data-v="${d.v}" data-t="${d.t}">${ic('checkc', 16)}Mark as Completed</button><button class="dd-i" data-act="mreschedule" data-v="${d.v}" data-t="${d.t}">${ic('cal', 16)}Reschedule</button><button class="dd-i" data-act="mcreatewo" data-v="${d.v}" data-t="${d.t}">${ic('wrench', 16)}Create Work Order</button><button class="dd-i" data-act="dl" data-name="${d.v}_service_history.pdf">${ic('download', 16)}Download History</button>`;
DDS.date = () => ['Thu, 26 Sep 2026', 'Wed, 25 Sep 2026', 'This Week', 'This Month', 'September 2026'].map(x => `<button class="dd-i" data-act="set" data-k="u:date" data-v="${x}">${x === (UI.date || TODAY) ? ic('check', 15) : '<span style="width:15px"></span>'}${x}</button>`).join('');
ACT.mmarkdone = d => { M().serviceDone.push(d.v + d.t); M().extraHistory.unshift({ d: '26 Sep 2026', t: d.t, wo: 'WO-2026-0' + (20 + M().extraHistory.length), desc: 'Marked completed from dashboard', cost: 4500, cat: 'Service', ic: 'tools', c: '#2563eb', bg: '#eaf1ff' }); save(); audit('Service completed', `${d.t} for ${d.v}`); toast(`${d.t} marked completed for ${d.v}`); refresh(); };
ACT.mreschedule = d => openModal(`Reschedule ${esc(d.t)}`, `<div class="fs13 mut mt8">${esc(d.v)}</div>${field('New date', '<input class="inp" type="date" name="date" value="2026-10-02"/>')}${field('Reason', '<input class="inp" name="r" placeholder="Workshop slot availability"/>')}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="mresched2">Save</button>`);
ACT.mresched2 = () => { closeModal(); toast('Service rescheduled'); };
ACT.mcritical = () => openModal('Critical Issues (4)', `<table class="tbl mt12"><thead><tr><th>Vehicle</th><th>Issue</th><th>Reported</th><th></th></tr></thead><tbody>${[['GJ01CD5678', 'Tire inspection overdue by 16 days'], ['GJ01GH3456', 'Engine overheating (breakdown)'], ['GJ01OP5566', 'Battery failure'], ['GJ01EF9012', 'Left rear tyre sidewall cut']].map(r => `<tr><td class="t1">${r[0]}</td><td>${r[1]}</td><td>Today</td><td><button class="btn btn-danger btn-sm" data-act="mcreatewo" data-v="${r[0]}" data-t="${r[1]}" data-ty="Repair">Create WO</button></td></tr>`).join('')}</tbody></table>`, '', 'lg');
ACT.mexport = () => toast('Service schedule exported as Excel');
ACT.minspgo = () => go(mlink('inspections'));
ACT.mlog = d => openModal('Log Service', `${field('Vehicle', `<input class="inp" name="v" value="${esc(d.v || 'GJ01EF9012')}"/>`)}${field('Service', sel('u:_x', ['Oil Change', 'Brake Inspection', 'Tire Rotation', 'General Service', 'AC Service'], 'Oil Change').replace('data-bind="u:_x"', 'name="t" data-norefresh'))}${field('Cost (₹)', '<input class="inp" name="cost" type="number" value="4500"/>')}${field('Odometer (KM)', '<input class="inp" name="km" value="42,580"/>')}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="mlog2">Save Log</button>`);
ACT.mlog2 = () => { const f = formVals(document.querySelector('.modal')); M().extraHistory.unshift({ d: '26 Sep 2026', t: f.t, wo: 'WO-2026-0' + (20 + M().extraHistory.length), desc: 'Logged at ' + f.km + ' km', cost: Number(f.cost) || 0, cat: 'Service', ic: 'tools', c: '#2563eb', bg: '#eaf1ff' }); save(); closeModal(); toast('Service logged'); refresh(); };
ACT.mschedule = d => openModal('Schedule Service', `<div class="g" style="grid-template-columns:1fr 1fr">${field('Vehicle', `<div class="sel" style="width:100%"><select name="v">${DATA.vehicles.slice(0, 12).map(v => `<option ${v.no === (d.v || mmVeh().no) ? 'selected' : ''}>${v.no}</option>`).join('')}</select>${ic('down', 15)}</div>`, 1)}${field('Service Type', `<div class="sel" style="width:100%"><select name="t">${['Oil Change', 'Brake Inspection', 'Tire Rotation', 'Engine Service', 'AC Service', 'General Checkup', 'Emission Check'].map(o => `<option>${o}</option>`).join('')}</select>${ic('down', 15)}</div>`, 1)}${field('Date', '<input class="inp" type="date" name="date" value="2026-10-05"/>', 1)}${field('Workshop', `<div class="sel" style="width:100%"><select name="w">${DATA.suppliers.map(s => `<option>${s.name}</option>`).join('')}<option>In-house Garage</option></select>${ic('down', 15)}</div>`)}</div>${field('Notes', '<textarea class="inp" name="n" placeholder="Optional"></textarea>')}`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="mschedule2">${ic('cal', 15)}Schedule</button>`);
ACT.mschedule2 = () => { const f = formVals(document.querySelector('.modal')); const v = allVehicles().find(x => x.no === f.v) || DATA.vehicles[0]; const dt = new Date(f.date); const ds = isNaN(dt) ? '05 Oct 2026' : dt.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }); M().schedule.unshift({ v: f.v, model: v.model, seats: v.seats + ' Seater', type: f.t, last: '-', next: ds, due: Math.max(0, Math.round((dt - new Date('2026-09-26')) / 864e5)) + ' days', status: 'Scheduled' }); save(); audit('Service scheduled', `${f.t} for ${f.v} on ${ds}`); closeModal(); toast(`${f.t} scheduled for ${f.v} on ${ds}`); refresh(); };
