ACT.wocomment = () => openModal('Add Comment', `<textarea class="inp mt12" id="woc" placeholder="Write a comment for the mechanic..."></textarea>`, `<button class="btn btn-outline" data-act="mclose">Cancel</button><button class="btn btn-primary" data-act="wocomment2">Post</button>`);
