  let body;
  if (t === 'Overview') body = `<div class="g mt12" style="grid-template-columns:repeat(3,1fr);gap:0;border:1px solid var(--line);border-radius:10px">${[['gauge', 'Total KM', v.km.replace(' km', ' km'), ''], ['shieldcheck', 'Next Service', '12 Oct 2026', 'in 15 days'], ['cal', 'Last Service', v.last, '5,000 km ago']].map((x, i) => `<div class="row" style="padding:10px;align-items:flex-start;${i ? 'border-left:1px solid var(--line)' : ''}">${ic(x[0], 22, 'style="color:#2563eb"')}<div><div class="fs11 mut">${x[1]}</div><div class="b fs13">${x[2]}</div>${x[3] ? `<div class="fs11 ${i === 1 ? 'c-green' : 'mut'}">${x[3]}</div>` : ''}</div></div>`).join('')}</div>
    <div class="g mt12" style="grid-template-columns:repeat(3,1fr);row-gap:14px">${[['Manufacturer', v.model.startsWith('Tata') ? 'Tata Motors' : v.model.split(' ')[0]], ['Model', v.model.split(' (')[0].split(' ').slice(1).join(' ') || 'Starbus'], ['Year', '2022'], ['Fuel Type', 'Diesel'], ['Seating Capacity', (v.model.match(/\d+/) || ['52'])[0]], ['Chassis No.', 'MAT4567890'], ['Engine No.', 'ENG789456'], ['Registration No.', `<b>${v.no}</b>`], ['Insurance Expiry', '<span class="c-red">15 Mar 2027</span>'], ['Fitness Expiry', '12 Jan 2027'], ['Warranty Expiry', '12 Aug 2027']].map(x => `<div><div class="fs11 mut">${x[0]}</div><div class="fs13 m5 mt4">${x[1]}</div></div>`).join('')}</div>`;
