function costPanel() { const t = UI.mct || 'Cost Breakdown'; return pnl(`Cost & Downtime - ${mmVeh().no}`, `<div class="g" style="grid-template-columns:1fr 1fr;gap:10px"><div class="sbox"><div class="row fs12 sb6">${tile('rupee', '#2563eb', '#eaf1ff', 26, 14, 7)}Total Maintenance Cost</div><div class="b fs20 mt8">₹45,500</div><div class="fs11 c-green row mt4">${ic('arrowd', 12)}12% from last period</div></div><div class="sbox"><div class="row fs12 sb6">${tile('clock', '#7c3aed', '#f3efff', 26, 14, 7)}Total Downtime</div><div class="b fs20 mt8">2.5 days</div><div class="fs11 c-green row mt4">${ic('arrowd', 12)}40% from last period</div></div></div>${mtabs('mct', ['Cost Breakdown', 'Downtime', 'Monthly Trend'], t)}${costBody(t)}`, { back: mlink('vehicles'), right: `<button class="btn btn-outline btn-sm" style="background:#fff" data-act="toast" data-msg="Range: Jan 2026 - Sep 2026">Jan 2026 - Sep 2026 ${ic('cal', 13)}</button>` }); }
