function purchaseTable(p) { const rows = [...M().extraPurchases.filter(x => x.code === p.code).map(x => [x.date, x.supplier, x.inv, x.qty, x.cost]), ...DATA.purchases]; return `<table class="tbl compact mt8"><thead><tr><th>Date</th><th>Supplier</th><th>Invoice No.</th><th>Quantity</th><th>Unit Cost</th><th>Total Cost</th></tr></thead><tbody>${rows.map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${inr(r[4])}</td><td>${inr(r[3] * r[4])}</td></tr>`).join('')}</tbody></table>`; }
