  return pnl(`Adjust Stock - ${esc(p.name)}`, `${mtabs('pat', ['Stock In (Purchase)', 'Stock Out (Consumption)', 'Manual Adjustment'], t)}${body}`, { back: mlink('parts'), right: `<button class="phb">${ic('more', 18)}</button>` });
