ACT.psicancel = () => { UI.psi = null; refresh(); };
ACT.pstockin = () => { const f = UI.psi, p = curPart(), q = Number(f.qty) || 0; if (q <= 0) { toast('Enter a quantity', 'warn'); return; } M().partQty[p.code] = partQty(p) + q; const dt = new Date(f.date); M().extraPurchases.unshift({ code: p.code, date: isNaN(dt) ? f.date : dt.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }), supplier: f.sup, inv: f.inv, qty: q, cost: Number(f.cost) || 0 }); UI.psi = null; save(); audit('Stock in', `${q} x ${p.name}`); toast(`${q} units of ${p.name} added. New stock: ${partQty(p)}`); refresh(); };
ACT.pmanual = () => { const v = Number(document.getElementById('pmadj').value), p = curPart(); M().partQty[p.code] = Math.max(0, v); save(); toast(`Stock set to ${v}`); refresh(); };
function consumptionForm() {
  const c = UI.pcf || (UI.pcf = { wo: 'WO-2026-014 (Brake Repair)', v: 'GJ01EF9012 - Tata Starbus', date: '2026-09-26', rows: [{ code: 'BRK-002', qty: 4 }, { code: 'BRK-003', qty: 2 }], rem: 'Brake pads and discs replaced.' });
  const lookup = code => code === 'BRK-003' ? { name: 'Brake Disc', code: 'BRK-003', cost: 4800, art: 'tyre', qty: 6 } : allParts().find(p => p.code === code);
  const total = c.rows.reduce((a, r) => a + (lookup(r.code) || { cost: 0 }).cost * r.qty, 0);
  return `<div class="g mt8" style="grid-template-columns:1fr 1fr;column-gap:12px">${field('Select Work Order (Optional)', sel('u:pcf.wo', [...M().workOrders.map(w => `${w.id} (${w.cat || w.type})`), 'WO-2026-014 (Brake Repair)'].filter((x, i, a) => a.indexOf(x) === i), c.wo, 'data-norefresh').replace('class="sel"', 'class="sel" style="width:100%"'))}${field('Vehicle (Optional)', sel('u:pcf.v', ['GJ01EF9012 - Tata Starbus', 'GJ01CD5678 - Ashok Leyland', 'GJ01GH3456 - Eicher'], c.v, 'data-norefresh').replace('class="sel"', 'class="sel" style="width:100%"'))}</div>${field('Date', `<input class="inp" type="date" style="width:200px" data-bind="u:pcf.date" value="${c.date}"/>`, 1)}
  <div class="row mt12"><span class="sec-t" style="flex:1;margin:0">Select Parts Used</span><button class="btn btn-primary btn-sm" data-act="dd" data-dd="pcfadd" data-w="240">${ic('plus', 14)}Add Part</button></div>
  <table class="tbl compact mt8"><thead><tr><th>Part</th><th>Available</th><th>Quantity Used</th><th>Unit Cost</th><th>Total Cost</th><th></th></tr></thead><tbody>${c.rows.map((r, i) => { const p = lookup(r.code) || {}; return `<tr><td><span class="row"><span style="width:26px;height:26px">${partArt(p.art)}</span><span><div class="m5">${p.name}</div><div class="t2">${p.code}</div></span></span></td><td>${p.code === 'BRK-003' ? 6 : partQty(p)}</td><td><input class="inp" style="width:64px;height:30px" type="number" min="1" data-bind="u:pcf.rows.${i}.qty" data-live value="${r.qty}"/></td><td>${inr(p.cost)}</td><td class="c-red">${inr(p.cost * r.qty)}</td><td><button class="ibtn" style="color:#ef4444;border:0" data-act="pcfdel" data-i="${i}">${ic('trash', 15)}</button></td></tr>`; }).join('')}</tbody></table>
  <div class="row mt8" style="justify-content:flex-end;gap:30px"><span class="fs13">Total Consumption Cost</span><b class="fs16">${inr(total)}</b></div>${field('Remarks (Optional)', `<textarea class="inp" data-bind="u:pcf.rem">${esc(c.rem)}</textarea>`)}
  <div class="row mt16" style="gap:10px"><button class="btn btn-soft btn-lg" style="flex:1" data-act="pcfcancel">Cancel</button><button class="btn btn-primary btn-lg" style="flex:1.6" data-act="pconsume">Record Consumption</button></div>`;
}
DDS.pcfadd = () => allParts().map(p => `<button class="dd-i" data-act="pcfadd" data-c="${p.code}"><span style="width:22px;height:22px">${partArt(p.art)}</span>${esc(p.name)}<span class="mut fs11" style="margin-left:auto">${partQty(p)}</span></button>`).join('');
ACT.pcfadd = d => { consumptionForm(); UI.pcf.rows.push({ code: d.c, qty: 1 }); refresh(); };
ACT.pcfdel = d => { UI.pcf.rows.splice(Number(d.i), 1); refresh(); };
ACT.pcfcancel = () => { UI.pcf = null; refresh(); };
ACT.pconsume = () => {
  const c = UI.pcf; if (!c.rows.length) { toast('Add at least one part', 'warn'); return; }
  for (const r of c.rows) { const p = allParts().find(x => x.code === r.code); if (p && Number(r.qty) > partQty(p)) { toast(`Only ${partQty(p)} ${p.name} available`, 'err'); return; } }
  const wo = c.wo.split(' ')[0];
  c.rows.forEach(r => { const p = allParts().find(x => x.code === r.code) || { name: 'Brake Disc', code: 'BRK-003', cost: 4800 }; if (DATA.parts.includes(p) || (M().extraParts || []).includes(p)) M().partQty[p.code] = partQty(p) - Number(r.qty); M().consumption.unshift({ code: p.code, part: p.name, qty: Number(r.qty), total: p.cost * r.qty, wo, vehicle: c.v.split(' ')[0], date: '26 Sep 2026' }); });
  UI.pcf = null; save(); audit('Stock consumed', `Parts issued to ${wo}`); toast(`Consumption recorded against ${wo}`); refresh();
};
